param([string]$ProjectPath='C:\Projects\gympro-api',[string]$BackupRoot='C:\Projects\gympro-backups')
$ErrorActionPreference='Stop'
$exitCode=0
$oldLocation=Get-Location
$names=@('NODE_ENV','GYMPRO_DEV_SESSION_WRITES','GYMPRO_DEV_SESSION_CONFIRM','PGPASSWORD','GYMPRO_B8_DB_PASSWORD')
$saved=@{}
foreach($name in $names){$saved[$name]=[Environment]::GetEnvironmentVariable($name,'Process')}
try {
    Set-Location -LiteralPath $ProjectPath
    if(-not (Test-Path '.\package.json')){throw 'Gym Pro package.json was not found.'}
    $node=(Get-Command node.exe -ErrorAction Stop).Source
    $npm=(Get-Command npm.cmd -ErrorAction Stop).Source
    $npx=(Get-Command npx.cmd -ErrorAction Stop).Source
    $report=Join-Path $BackupRoot ('completion-batch1-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6))
    New-Item -ItemType Directory -Path $report -Force | Out-Null
    $payload=([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json)
    $utf8=New-Object Text.UTF8Encoding($false)
    # Check all destinations before writing. Identical existing files are reusable.
    foreach($entry in $payload.PSObject.Properties){
        $target=Join-Path $ProjectPath $entry.Name
        if((Test-Path -LiteralPath $target) -and [IO.File]::ReadAllText($target) -cne $entry.Value){throw "Existing file differs; retained without overwrite: $($entry.Name)"}
    }
    $runnerTarget=Join-Path $ProjectPath 'scripts\completion-batch1-baseline.ps1'
    $runnerText=[IO.File]::ReadAllText($PSCommandPath)
    if((Test-Path -LiteralPath $runnerTarget) -and [IO.File]::ReadAllText($runnerTarget) -cne $runnerText){throw 'Existing baseline runner differs; retained without overwrite.'}
    foreach($entry in $payload.PSObject.Properties){
        $target=Join-Path $ProjectPath $entry.Name
        New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null
        if(-not(Test-Path -LiteralPath $target)){[IO.File]::WriteAllText($target,$entry.Value,$utf8)}
    }
    if(-not(Test-Path -LiteralPath $runnerTarget)){[IO.File]::WriteAllText($runnerTarget,$runnerText,$utf8)}
    foreach($name in @('GYMPRO_DEV_SESSION_WRITES','GYMPRO_DEV_SESSION_CONFIRM','PGPASSWORD','GYMPRO_B8_DB_PASSWORD')){[Environment]::SetEnvironmentVariable($name,$null,'Process')}
    $env:NODE_ENV='test'
    Write-Host 'CHECK: Redacted configuration and source preflight' -ForegroundColor Cyan
    & $node '.\scripts\completion-preflight.mjs' $ProjectPath (Join-Path $report 'preflight.json')
    if($LASTEXITCODE -ne 0){throw 'Configuration preflight failed; review FAIL names. Do not send database URL values.'}
    Write-Host 'CHECK: Nest build' -ForegroundColor Cyan
    & $npm run build
    if($LASTEXITCODE -ne 0){throw 'Build failed.'}
    Write-Host 'CHECK: Full unit suite' -ForegroundColor Cyan
    & $npx --no-install vitest run '--reporter=default' '--reporter=json' "--outputFile.json=$report\unit-results.json"
    if($LASTEXITCODE -ne 0){throw 'Unit suite failed.'}
    Write-Host 'CHECK: Existing root e2e suite' -ForegroundColor Cyan
    & $npx --no-install vitest run --config './vitest.config.e2e.ts' '--reporter=default' '--reporter=json' "--outputFile.json=$report\e2e-results.json"
    if($LASTEXITCODE -ne 0){throw 'Root e2e failed.'}
    $units=Get-Content (Join-Path $report 'unit-results.json') -Raw | ConvertFrom-Json
    $e2e=Get-Content (Join-Path $report 'e2e-results.json') -Raw | ConvertFrom-Json
    foreach($result in @($units,$e2e)){
        if($result.success -ne $true -or $result.numPassedTests -lt 1 -or $result.numFailedTests -ne 0 -or $result.numPendingTests -gt 0 -or $result.numTodoTests -gt 0){throw 'Test summary did not establish an entirely passing suite.'}
    }
    $summary=[ordered]@{batch='1A foundation baseline';configurationPreflightPassed=$true;buildPassed=$true;unitTestsPassed=$units.numPassedTests;rootE2ePassed=$e2e.numPassedTests;businessHttpRegressionRerun=$false;browserAcceptanceRerun=$false;databaseMigrationApplied=$false;productionLoginChanged=$false;cleanInstallVerified=$false;migrationLedgerInstalled=$false;kbzPayDeferred=$true;gitCommitPerformed=$false;verifiedAt=(Get-Date -Format o)}
    $summary | ConvertTo-Json | Set-Content (Join-Path $report 'batch1-summary.json') -Encoding UTF8
    Write-Host 'PASS: Batch 1A baseline and acceptance register installed; configuration, build, unit and root e2e checks passed.' -ForegroundColor Green
    Write-Host 'PENDING: Clean install, migration ledger, production authentication and business/browser acceptance.'
    Write-Host 'No database migration, login-policy change, operator styling change or Git commit performed.'
    Write-Host "Reports: $report"
} catch {
    $exitCode=1
    Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red
    if($report){Write-Host "Keep reports: $report"}
    Write-Host 'Installed baseline files are retained. Do not reinstall other batches to resolve this failure.'
} finally {
    foreach($name in $names){[Environment]::SetEnvironmentVariable($name,$saved[$name],'Process')}
    Set-Location $oldLocation
}
exit $exitCode
